function navigationSection(page){if(page==='access')return 'access';if(['home','institution','archive'].includes(page))return 'home';if(['browse','material','experiences','story','source-example'].includes(page))return 'browse';if(['mutual','community-topic','community-write','topic','topic-draft','community-rules'].includes(page))return 'mutual';if(['account','intake-status','intake-mod','backup','community-mod'].includes(page))return 'account';return ''}
function syncNavigationLayout(){const fold=document.querySelector('.mobile-map');if(!fold)return;const desktop=window.innerWidth>700;if(desktop)fold.open=true;else if(fold.dataset.layout==='desktop')fold.open=false;fold.dataset.layout=desktop?'desktop':'mobile'}
window.addEventListener('resize',syncNavigationLayout);
function closeHeaderMore(){const menu=$('header-more');if(menu)menu.open=false;}
document.addEventListener('click',e=>{const menu=$('header-more');if(menu?.open&&(!menu.contains(e.target)||e.target.closest('a')))closeHeaderMore()});
document.addEventListener('keydown',e=>{const menu=$('header-more');if(e.key==='Escape'&&menu?.open){closeHeaderMore();menu.querySelector('summary')?.focus()}});
'use strict';
let activeShare=null;
function saveBlob(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function zipFiles(files){const table=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0}const local=[],central=[],enc=new TextEncoder();let offset=0,centralSize=0;for(const f of files){let crc=0xffffffff;for(const b of f.bytes)crc=table[(crc^b)&255]^(crc>>>8);crc=(crc^0xffffffff)>>>0;const name=enc.encode(f.name),l=new Uint8Array(30+name.length),c=new Uint8Array(46+name.length),lv=new DataView(l.buffer),cv=new DataView(c.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint16(12,33,true);lv.setUint32(14,crc,true);lv.setUint32(18,f.bytes.length,true);lv.setUint32(22,f.bytes.length,true);lv.setUint16(26,name.length,true);l.set(name,30);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,33,true);cv.setUint32(16,crc,true);cv.setUint32(20,f.bytes.length,true);cv.setUint32(24,f.bytes.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);c.set(name,46);local.push(l,f.bytes);central.push(c);offset+=l.length+f.bytes.length;centralSize+=c.length}const end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,centralSize,true);e.setUint32(16,offset,true);return new Blob([...local,...central,end],{type:'application/zip'})}
function shareRecord(path){const [type,id]=path.split('/');const record=type==='institution'?getInstitution(id):type==='story'?stories.find(s=>s.id===id):getMaterial(id);if(!record)return null;return {type,id,record,title:record.name||record.title,summary:record.summary||record.paragraphs?.[0]||'',package:'packages/'+(type==='institution'?'institution-':type==='story'?'story-':'')+id+'.zip'}}
function recordURL(s){const url=new URL(location.href);url.hash=s.type+'/'+s.id;return url.href}
function shareText(s){const i=s.type==='institution'?s.record:getInstitution(s.record.institution);return `【虚构演示资料】${s.title}\n${s.summary}\n${i?'相关机构：'+i.name+'｜'+i.region+' · '+i.city+'\n':''}来源：看见阶段概念站，非真实机构、事件或证词\n编号：${s.id} · v${DATA.version}\n${recordURL(s)}`}
function showShare(path){const s=shareRecord(path);if(!s)return;activeShare=s;const local=location.protocol==='file:'||['localhost','127.0.0.1'].includes(location.hostname);$('share-content').innerHTML=`<h3>${esc(s.title)}</h3><p class="notice">${local?'当前本机地址无法供别人远程访问；可以分享下载包，或先发布公开副本。':'游客可直接打开公开页面；分享时请保留来源、核对状态和版本。'}</p><div class="share-snippet">${esc(shareText(s))}</div><div class="dialog-actions">${typeof navigator.share==='function'?'<button class="primary" id="native-share">'+icon('share-2')+'通过系统分享</button>':''}<button ${typeof navigator.share==='function'?'':'class="primary"'} id="copy-share">${icon('copy')}复制标题、说明与链接</button><a class="button" href="${s.package}" download>${icon('package')}保存${s.type==='institution'?'机构':s.type==='story'?'经历':'完整'}资料包</a>${s.type==='material'?`<a class="button" href="${s.record.file}" download>${icon('download')}只保存${s.record.kind==='视频'?'视频':'图片'}文件</a>`:''}<button id="save-share-note">${icon('file-text')}保存文字说明</button></div><p class="muted">资料包保留来源、演示标记与版本。私人投稿原件不会进入此包。</p>`;$('share-dialog').showModal()}
async function copyShare(){const text=shareText(activeShare);try{await navigator.clipboard.writeText(text);notify('已复制标题、说明与链接。')}catch{const a=document.createElement('textarea');a.value=text;document.body.append(a);a.select();const copied=document.execCommand('copy');a.remove();if(copied)notify('已复制标题、说明与链接。');else{saveBlob('分享说明.txt',new Blob([text],{type:'text/plain;charset=utf-8'}));notify('浏览器没有允许复制，已提供说明文件保存。')}}}
function route(){document.querySelectorAll('video').forEach(v=>v.pause());let [page='home',id]=location.hash.slice(1).split('/');if(!page||page==='institutions')page='home';if(page==='help')page='provide';let html,record;switch(page){case 'home':html=renderHome();break;case 'institution':record=getInstitution(id);if(record)html=renderInstitution(record);break;case 'material':record=getMaterial(id);if(record)html=renderMaterial(record);break;case 'story':record=stories.find(s=>s.id===id);if(record)html=renderStory(record);break;case 'browse':html=renderArchiveBrowse();break;case 'experiences':html=renderExperiences();break;case 'source-example':html=renderSourceExample();break;case 'provide':if(id&&getInstitution(id))draft.institution=id;html=renderProvide();break;case 'participate':html=renderParticipate();break;case 'mutual':html=renderCommunity();break;case 'community-topic':html=renderCommunityShell('互助讨论');break;case 'community-write':html=renderCommunityShell('整理自己的问题');break;case 'account':html=renderCommunityShell('我的内容');break;case 'community-mod':html=renderCommunityShell('处理审核');break;case 'community-rules':html=renderCommunityRules();break;case 'topic':record=DATA.topics.find(t=>t.id===id);if(record)html=renderTopic(record);break;case 'topic-draft':html=renderCommunityShell('整理自己的问题');page='community-write';break;case 'feedback':html=renderIntakeFeedback(id);break;case 'intake-status':html=renderIntakeStatus(id);break;case 'intake-mod':html=renderIntakeMod();break;case 'archive':html=renderLiveArchiveShell();break;case 'access':html=renderAccess();break;case 'backup':html=renderBackup();break;case 'review':html=renderReview();break;case 'about':html=renderAbout();break}if(!html){html=`<div class="content-column empty"><h1>没有找到这个页面</h1><p>地址可能已经变化，可以从机构列表重新查找。</p><a class="button primary" href="#home">返回机构列表</a></div>`}const section=navigationSection(page);$('main').innerHTML=html;closeHeaderMore();document.querySelectorAll('[data-nav],[data-header-nav]').forEach(a=>{const target=a.dataset.nav||a.dataset.headerNav;if(target===section)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelectorAll('[data-more-nav]').forEach(a=>{if(a.dataset.moreNav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const provideLink=document.querySelector('.contribute-link');if(provideLink){if(page==='provide')provideLink.setAttribute('aria-current','page');else provideLink.removeAttribute('aria-current')};if(page==='home'){renderResults();syncNavigationLayout();}if(page==='browse')renderMaterialResults();document.title=(record?.name||record?.title||({'experiences':'经历记录','source-example':'真实来源照片示例','home':'机构资料','browse':'资料与影像','provide':'整理资料','feedback':'补充与更正','mutual':'互助交流','participate':'一起参与','review':'资料处理演示','about':'关于本站','topic-draft':'整理问题','community-write':'整理问题','community-topic':'互助讨论','account':'我的内容','community-mod':'审核与反馈','community-rules':'社区公约','intake-status':'私人投稿进度','intake-mod':'资料核对','archive':'公开机构档案','access':'下载与保存','backup':'私人备份'})[page]||'页面')+' · 戒网瘾机构观察';window.scrollTo(0,0);communityHydrate(page,id);intakeHydrate(page,id);archiveHydrate(page,id);if(page==='backup')backupHydrate()}
document.addEventListener('input',e=>{if(e.target.id==='material-query')renderMaterialResults()});
document.addEventListener('change',e=>{if(e.target.id==='material-kind')renderMaterialResults()});
document.addEventListener('click',async e=>{const share=e.target.closest('[data-share]');if(share)showShare(share.dataset.share);if(e.target.closest('[data-close]'))e.target.closest('dialog').close();if(e.target.closest('#copy-share')&&activeShare)copyShare();if(e.target.closest('#save-share-note')&&activeShare){const r=activeShare.record,body=r.paragraphs||r.body||[r.summary];saveBlob(activeShare.id+'-说明.txt',new Blob([shareText(activeShare)+'\n\n'+body.join('\n\n')],{type:'text/plain;charset=utf-8'}))}if(e.target.closest('#native-share')&&activeShare){try{await navigator.share({title:activeShare.title,text:shareText(activeShare),url:recordURL(activeShare)})}catch(err){if(err.name!=='AbortError')notify('系统分享没有完成，可以复制说明或保存资料包。')}}const tab=e.target.closest('[data-inst-tab]');if(tab){const i=getInstitution(tab.dataset.inst),content=$('institution-tab-content');document.querySelectorAll('[data-inst-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===tab)));content.setAttribute('aria-label',tab.textContent);content.innerHTML=tab.dataset.instTab==='materials'?'<h2 class="section-head">公开资料</h2>'+i.materials.map(getMaterial).map(materialRow).join(''):tab.dataset.instTab==='stories'?(i.stories.length?i.stories.map(id=>stories.find(s=>s.id===id)).map(storyRow).join(''):'<div class="empty"><h3>还没有关联的经历示例</h3><p>资料可以逐步补充，不据此判断有没有相关经历。</p></div>'):'<h2 class="section-head">更新记录</h2><div class="reading"><p>2026.10.08 · v0.2：整理虚构机构、媒体与经历的关联。</p><p class="muted">没有真实投诉或更正事件。</p></div>'}const review=e.target.closest('[data-review]');if(review){$('review-status').textContent='演示状态：'+review.dataset.review+'。此操作只改变当前页面，没有更新真实记录。'+($('review-note').value.trim()?' 处理说明已在本页保留。':'')}});
$('share-dialog').addEventListener('click',e=>{if(e.target===$('share-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.addEventListener('submit',e=>{if(e.target.id!=='topic-form')return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),feedback=e.target.id==='feedback-form';saveBlob(feedback?'反馈-私人草稿.json':'问题-本机草稿.json',new Blob([JSON.stringify({format:feedback?'kanjian-feedback-draft-v1':'kanjian-topic-draft-v1',isSubmission:false,isPublic:false,created:new Date().toISOString(),...d},null,2)],{type:'application/json;charset=utf-8'}));notify('已请求保存草稿，没有发送、受理或发布。')});
window.addEventListener('hashchange',route);route();

document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();$('main').focus()});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-inst-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...document.querySelectorAll('[data-inst-tab]')],n=tabs.indexOf(tab);e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(n+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus()});
